class Bird {
	fly(): string {
		return "flying";
	}
}

class Penguin extends Bird {
	fly(): string {
		throw new Error("penguins cannot fly");
	}
}

function release(birds: Bird[]): string[] {
	return birds.map((bird) => bird.fly());
}

