class Account {
	protected balance = 0;

	// Contract: after withdraw, the balance is never negative.
	withdraw(amount: number): void {
		if (amount > this.balance) throw new Error("insufficient funds");
		this.balance -= amount;
	}
}

class OverdraftAccount extends Account {
	withdraw(amount: number): void {
		this.balance -= amount;
	}
}

