interface UserFinder {
	// Contract: returns null when no user has this id.
	find(id: string): User | null;
}

class CachedUserFinder implements UserFinder {
	find(id: string): User | null {
		const user = this.cache.get(id);
		if (user === undefined) throw new Error(`user ${id} not found`);
		return user;
	}
}

function greet(finder: UserFinder, id: string): string {
	const user = finder.find(id);
	return user === null ? "Hello, guest" : `Hello, ${user.name}`;
}

